    "Testimonial Details": "Testimonial Details",
    "Thank you for shopping with us!": "আমাদের সাথে কেনাকাটা করার জন্য ধন্যবাদ!",
    "Thank you for your business!": "আমাদের সাথে ব্যবসা করার জন্য ধন্যবাদ!",
    "The specified serial number does not match any purchase or sales records in the database.": "প্রদত্ত সিরিয়াল নম্বরটির সাথে ডাটাবেসের কোনো ক্রয় বা বিক্রয় রেকর্ডের মিল পাওয়া যায়নি।",
    "The system checks invoice date and warranty duration. If eligible, customer and sale details will auto-fill. If expired or out-of-warranty, details will still be displayed with an override option.": "সিস্টেম ইনভয়েস তারিখ ও ওয়ারেন্টির মেয়াদ যাচাই করে। প্রযোজ্য হলে গ্রাহক ও বিক্রয়ের তথ্য নিজে থেকেই পূরণ হবে। মেয়াদ উত্তীর্ণ হলে তা প্রদর্শিত হবে এবং পেইড সার্ভিস হিসেবে গ্রহণের সুযোগ থাকবে।",
